class Solution {
    public int hammingDistance(int x, int y) {
        int bits = x ^ y;
        int distance = 0;
        while (bits != 0) {
            distance++;
            bits &= bits - 1;
        }
        return distance;
    }
}

class Solution {
    public int hammingDistance(int x, int y) {
        int bits = x ^ y;
        int distance = 0;
        for (int position = 0; position < 31; position++) {
            distance += bits & 1;
            bits >>>= 1;
        }
        return distance;
    }
}

class Solution {
    private static final int[] NIBBLE_BITS = {
            0, 1, 1, 2,
            1, 2, 2, 3,
            1, 2, 2, 3,
            2, 3, 3, 4
    };

    public int hammingDistance(int x, int y) {
        int bits = x ^ y;
        int distance = 0;
        for (int chunk = 0; chunk < 8; chunk++) {
            distance += NIBBLE_BITS[bits & 15];
            bits >>>= 4;
        }
        return distance;
    }
}
